class Card {
    private String name;
    private int value;
    Card(String name, int value) { this.name = name; this.value = value; }
    int getValue() { return value; }
}

class Deck {
    private final Card[] cards = new Card[52];
    private int nextItem = 0;

    Deck() {
        for (int i = 0; i < 52; i++)
            cards[i] = new Card("c" + i, Math.min(i % 13 + 1, 10));
    }
    Card getNextCard() { return cards[nextItem++]; }
    int getDeckSize() { return 52 - nextItem; }
}

import java.util.*;

class Course { private String courseName = "OODP"; String getCourseName() { return courseName; } }
class Result {
    private String grade = "A"; private Course course = new Course();
    Course getCourse() { return course; }
    String getGrade() { return grade; }
}
class Student { private List<Result> results = new ArrayList<>(); List<Result> getResults() { return results; } }
class Professor { private List<Student> mentees = new ArrayList<>(); List<Student> getMentees() { return mentees; } }

class AppMgr {
    void showMenteeResults(Professor p) {
        for (Student s : p.getMentees())
            for (Result r : s.getResults()) {
                Course c = r.getCourse();
                System.out.println(c.getCourseName() + ": " + r.getGrade());
            }
    }
}

