class Transport {
    static final int BUS = 0, TAXI = 1, MRT = 2;
    private int type;
    private double distance;

    Transport(int type, double distance) { this.type = type; this.distance = distance; }

    double calFare() {
        double fare;
        switch (type) {
            case BUS:  fare = 0.9 + 0.10 * distance; break;
            case TAXI: fare = 3.2 + 0.50 * distance; break;
            case MRT:  fare = 0.8 + 0.08 * distance; break;
            default:   fare = 0;
        }
        return fare;
    }
}

