class Account { String summary() { return "S"; } String log() { return "L"; } }
class View { final String text; View(String t) { text = t; } }

class AccountInfoDisplay {
    public View format(Account acc) {
        if (acc == null) return new View("");
        return new View(acc.summary() + acc.log());   // full details
    }
}
class ATMDisplay extends AccountInfoDisplay {
    @Override
    public View format(Account acc) {
        // assumes the client has already checked acc != null
        return new View(acc.summary());               // partial details
    }
}

